(()=>{
    const form=document.querySelector('#estimate-form'), result=document.querySelector('#result'), button=document.querySelector('#submit'),searchPanel=document.querySelector('#search-panel'),searchToggle=document.querySelector('#search-toggle');
    const propertyType=document.querySelector('#property-type');
    function syncPropertyType(){const apartment=propertyType.value==='Appartement';document.querySelector('#terrain-field').hidden=apartment;form.terrain.disabled=apartment}
    propertyType.addEventListener('change',syncPropertyType);
    const initialResultHtml=result.innerHTML;
    function setSearchCollapsed(collapsed){const hasResult=result.dataset.state==='success';searchPanel.dataset.collapsed=String(collapsed);searchToggle.setAttribute('aria-expanded',String(!collapsed));document.querySelector('#search-toggle-text').textContent=collapsed?(hasResult?'Modifier':'Afficher'):'Masquer';document.querySelector('#mobile-search-title').textContent=collapsed?(hasResult?'Estimation prête':'Votre recherche'):(hasResult?'Modifier l’estimation':'Créer une estimation')}
    searchToggle.addEventListener('click',()=>setSearchCollapsed(searchPanel.dataset.collapsed!=='true'));
    const euro=new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:0});
    const number=new Intl.NumberFormat('fr-FR',{maximumFractionDigits:0});
    const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const median=values=>{let a=[...values].sort((x,y)=>x-y),m=Math.floor(a.length/2);return a.length%2?a[m]:(a[m-1]+a[m])/2};
    const quantile=(values,q)=>{let a=[...values].sort((x,y)=>x-y),i=(a.length-1)*q,l=Math.floor(i),f=i-l;return a[l]+(a[Math.min(l+1,a.length-1)]-a[l])*f};
    const distance=(a,b,c,d)=>{const r=Math.PI/180,dl=(c-a)*r,dp=(d-b)*r,v=Math.sin(dp/2)**2+Math.cos(b*r)*Math.cos(d*r)*Math.sin(dl/2)**2;return 12742*Math.asin(Math.sqrt(v))};
    async function json(url){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{let res=await fetch(url,{signal:controller.signal});if(!res.ok)throw Error('Service indisponible ('+res.status+').');return await res.json()}finally{clearTimeout(timer)}}
    function bbox(coords,box=[Infinity,Infinity,-Infinity,-Infinity]){if(typeof coords[0]==='number'){box[0]=Math.min(box[0],coords[0]);box[1]=Math.min(box[1],coords[1]);box[2]=Math.max(box[2],coords[0]);box[3]=Math.max(box[3],coords[1])}else for(const c of coords)bbox(c,box);return box}
    function boxDistance(lon,lat,box){return distance(lon,lat,Math.max(box[0],Math.min(lon,box[2])),Math.max(box[1],Math.min(lat,box[3])))}
    function status(text){result.dataset.state='loading';result.innerHTML='<div class="empty"><span class="empty-icon" aria-hidden="true">⌕</span><h2>Recherche en cours</h2><p>'+escape(text)+'</p></div>'}
    function message(title,body,kind=''){result.dataset.state='message';result.innerHTML='<div class="empty"><span class="empty-icon" aria-hidden="true">⌕</span><h2>'+escape(title)+'</h2><p>'+escape(body)+'</p>'+(kind?'<div class="notice error">Vous pouvez réessayer dans quelques instants.</div>':'')+'</div>'}
    async function geocode(address){const post=address.match(/\b\d{5}\b/)?.[0];if(!post)throw Error('Ajoutez le code postal à l’adresse pour identifier la bonne commune.');const data=await json('https://data.geopf.fr/geocodage/search?q='+encodeURIComponent(address)+'&limit=1');const feature=data.features?.[0];if(!feature||feature.properties.score<.55||!feature.properties.citycode||feature.properties.postcode!==post)throw Error('Adresse introuvable. Vérifiez le numéro, la rue, le code postal et la commune.');return feature}
    const addressInput=document.querySelector('#address'),addressOptions=document.querySelector('#address-options');
    let completionTimer,completionRequest,completionSequence=0,mode='address';
    addressInput.addEventListener('input',()=>{
      clearTimeout(completionTimer);completionRequest?.abort();addressOptions.replaceChildren();
      const query=addressInput.value.trim(),sequence=++completionSequence;
      if(query.length<4)return;
      completionTimer=setTimeout(async()=>{
        completionRequest=new AbortController();
        try{
          const url='https://data.geopf.fr/geocodage/completion?text='+encodeURIComponent(query)+'&maximumResponses=6';
          const response=await fetch(url,{signal:completionRequest.signal});if(!response.ok)return;
          const data=await response.json();if(sequence!==completionSequence)return;
          for(const item of data.results||[]){if(!item.fulltext)continue;const option=document.createElement('option');option.value=item.fulltext;addressOptions.append(option)}
        }catch(error){if(error.name!=='AbortError')addressOptions.replaceChildren()}
      },250);
    });
    function setMode(next){mode=next;document.querySelector('#address-mode').setAttribute('aria-pressed',String(next==='address'));document.querySelector('#parcel-mode').setAttribute('aria-pressed',String(next==='parcel'));document.querySelector('#address-fields').hidden=next!=='address';document.querySelector('#parcel-fields').hidden=next!=='parcel';addressInput.required=next==='address';document.querySelector('#parcel-ref').required=next==='parcel';addressOptions.replaceChildren()}
    document.querySelector('#address-mode').addEventListener('click',()=>setMode('address'));
    document.querySelector('#parcel-mode').addEventListener('click',()=>setMode('parcel'));
    async function parcelLocation(reference,city){
      const ref=reference.toUpperCase().replace(/[^A-Z0-9]/g,'');let code,prefix='000',section,parcelNumber;
      const full=ref.match(/^(\d{5})(\d{3})([A-Z0-9]{2})(\d{4})$/);
      if(full){[,code,prefix,section,parcelNumber]=full}
      else{
        const short=ref.match(/^([A-Z]{1,2})0*(\d{1,4})$/);
        if(!short)throw Error('Référence attendue : AD 243 ou 33063000AD0243.');
        if(!city.trim())throw Error('Ajoutez la commune et son code postal pour retrouver la parcelle.');
        const post=city.match(/\b\d{5}\b/)?.[0];if(!post)throw Error('Ajoutez le code postal à la commune.');
        const geo=await json('https://data.geopf.fr/geocodage/search?q='+encodeURIComponent(city)+'&type=municipality&limit=1');
        const match=geo.features?.[0];if(!match||match.properties.score<.55||match.properties.postcode!==post)throw Error('Commune introuvable. Vérifiez son nom et son code postal.');
        code=match.properties.citycode;section=short[1].padStart(2,'0');parcelNumber=short[2].padStart(4,'0');
      }
      const params=new URLSearchParams({code_insee:code,section,numero:parcelNumber});if(prefix!=='000')params.set('com_abs',prefix);
      const data=await json('https://apicarto.ign.fr/api/cadastre/parcelle?'+params);
      let found=(data.features||[]).filter(f=>f.properties?.code_insee===code&&f.properties?.section===section&&f.properties?.numero===parcelNumber);
      if(full)found=found.filter(f=>f.properties.idu===ref);
      if(!found.length)throw Error('Parcelle introuvable. Vérifiez la commune, la section et le numéro.');
      if(found.length>1)throw Error('Plusieurs parcelles portent cette référence. Utilisez la référence cadastrale complète.');
      const parcel=found[0],box=bbox(parcel.geometry.coordinates),lon=(box[0]+box[2])/2,lat=(box[1]+box[3])/2;
      return {type:'Feature',geometry:{type:'Point',coordinates:[lon,lat]},properties:{label:'Parcelle '+section+' '+Number(parcelNumber)+' · '+parcel.properties.nom_com,citycode:code,parcelArea:parcel.properties.contenance,parcelId:parcel.properties.idu}};
    }
    function dvfSectionCode(properties){const raw=String(properties.code??'').trim().toUpperCase();if(!raw)return null;const code=String(properties.prefixe??'000').padStart(3,'0')+raw.padStart(2,'0');return /^\d{3}[A-Z0-9]{2}$/.test(code)?code:null}
    async function salesForSections(code,sections){const out=[];for(let i=0;i<sections.length;i+=3){const batch=sections.slice(i,i+3);const values=await Promise.allSettled(batch.map(async s=>{let data=await json('https://dvf-api.data.gouv.fr/mutations/'+encodeURIComponent(code)+'/'+encodeURIComponent(s.code));return data.data||[]}));for(const v of values)if(v.status==='fulfilled')out.push(...v.value);if(i===0&&values.every(v=>v.status==='rejected'))throw Error('Les données de ventes sont momentanément indisponibles.');if(out.length>5000)break}return out}
    function cleanSales(rows,lon,lat,surface,terrain,type){const groups=new Map(),cutoff=new Date();cutoff.setFullYear(cutoff.getFullYear()-5);for(const row of rows){if(row.nature_mutation!=='Vente'||row.type_local!==type)continue;const price=Number(row.valeur_fonciere),area=Number(row.surface_reelle_bati),x=Number(row.longitude),y=Number(row.latitude),date=new Date(row.date_mutation),land=Number(row.surface_terrain);if(!Number.isFinite(price)||!Number.isFinite(area)||!Number.isFinite(x)||!Number.isFinite(y)||!Number.isFinite(date.getTime())||date<cutoff||date>new Date()||area<1||price<=0)continue;const km=distance(lon,lat,x,y),sqm=price/area;if(km>10||sqm<400||sqm>30000)continue;const key=row.id_mutation+'-'+row.numero_disposition;const signature=area+'-'+row.id_parcelle;let group=groups.get(key);if(!group){group={seen:new Set(),houses:[]};groups.set(key,group)}if(group.seen.has(signature))continue;group.seen.add(signature);group.houses.push({price,area,land:Number.isFinite(land)?land:0,rooms:Number(row.nombre_pieces_principales)||0,km,date:row.date_mutation,sqm,street:row.adresse_nom_voie||row.nom_commune||'Vente',parcel:row.id_parcelle})}
      return [...groups.values()].filter(g=>g.houses.length===1).map(g=>g.houses[0])}
    function choose(sales,surface,terrain){
      const tiers=[
        {km:1.5,months:30,min:.6,max:1.5},
        {km:3,months:36,min:.6,max:1.5},
        {km:5,months:60,min:.6,max:1.5},
        {km:5,months:60,min:.4,max:2,relaxed:true},
        {km:10,months:60,min:0,max:Infinity,relaxed:true}
      ];
      let fallback;
      for(const tier of tiers){
        let selected=sales.filter(s=>s.km<=tier.km&&(Date.now()-new Date(s.date).getTime())/2629800000<=tier.months&&s.area>=surface*tier.min&&s.area<=surface*tier.max);
        let terrainApplied=false;
        if(terrain>0&&!tier.relaxed){const matching=selected.filter(s=>!s.land||s.land>=terrain*.35&&s.land<=terrain*2.8);if(matching.length>=4){selected=matching;terrainApplied=true}}
        fallback={selected,tier,terrainApplied};
        if(selected.length>=4)return fallback;
      }
      return fallback;
    }
    function relevanceScore(s,surface){const area=Math.max(0,1-Math.abs(s.area-surface)/(surface*.5)),near=Math.max(0,1-s.km/5),recent=Math.max(0,Math.min(1,1-(Date.now()-new Date(s.date).getTime())/2629800000/60));return Math.round(45*area+35*near+20*recent)}
    function render(feature,surface,terrain,sales,picked,type){result.dataset.state='success';const selected=picked.selected,tier=picked.tier,label=feature.properties.label,km=Math.max(...selected.map(s=>s.km)),prices=selected.map(s=>s.sqm),center=median(prices)*surface,low=quantile(prices,.25)*surface,high=quantile(prices,.75)*surface,latest=selected.map(s=>s.date).sort().at(-1),shown=[...selected].map(s=>({...s,relevance:relevanceScore(s,surface)})).sort((a,b)=>b.relevance-a.relevance||a.km-b.km).slice(0,6);const confidence=selected.length<3?'Repère très limité':tier.relaxed||median(selected.map(s=>relevanceScore(s,surface)))<50?'Comparabilité faible':selected.length>=12?'Échantillon solide':selected.length>=6?'Échantillon modéré':'Échantillon limité';result.innerHTML='<div class="output">'+(tier.relaxed?'<div class="notice">Recherche élargie : trop peu de ventes du même type proches de vos critères. Les surfaces peuvent être très différentes ; le filtre sur le terrain est levé. Le montant est un repère fragile.</div>':'')+'<div class="result-head"><div><p class="eyebrow">Estimation fondée sur les ventes</p><h2>Valeur indicative</h2></div><div class="result-actions"><span class="badge">'+confidence+'</span><button type="button" class="new-estimate-button">Nouvelle estimation</button><button type="button" class="print-button">Imprimer / enregistrer en PDF</button></div></div><p class="address">'+escape(label)+(feature.properties.parcelArea?' · Contenance cadastrale : '+number.format(feature.properties.parcelArea)+' m²':'')+'</p><p class="report-context">'+escape(type)+' · Surface habitable : '+number.format(surface)+' m²'+(terrain>0?' · Terrain déclaré : '+number.format(terrain)+' m²':'')+' · Édité le '+new Intl.DateTimeFormat('fr-FR',{dateStyle:'long'}).format(new Date())+'</p><div class="value">'+euro.format(center)+'</div>'+(selected.length>=3?'<p class="range">Fourchette observée&nbsp;: <strong>'+euro.format(low)+' – '+euro.format(high)+'</strong></p>':'<p class="range">Seulement '+selected.length+' vente(s) : projection indicative, sans fourchette statistique.</p>')+'<div class="metrics"><div class="metric"><b>'+number.format(selected.length)+'</b><span>ventes retenues</span></div><div class="metric"><b>'+number.format(median(prices))+' €</b><span>prix médian / m²</span></div><div class="metric"><b>'+number.format(km*1000)+' m</b><span>vente la plus éloignée</span></div></div><div class="selection-scope"><strong>Périmètre utilisé pour le calcul</strong>Parmi les secteurs cadastraux consultés : ventes à moins de '+String(tier.km).replace('.',',')+' km, sur les '+tier.months+' derniers mois, '+(tier.max===Infinity?'sans restriction de surface': 'pour des biens de '+number.format(surface*tier.min)+' à '+number.format(surface*tier.max)+' m²')+'. '+(picked.terrainApplied?'Filtre terrain appliqué (35 à 280 % de votre terrain, valeurs manquantes admises).':'Aucun filtre sur le terrain.')+'</div><h3 class="section-title">Ventes comparables</h3><p class="note">'+number.format(shown.length)+' ventes affichées sur '+number.format(selected.length)+' retenues, classées par pertinence. Score sur 100 : surface (45 points), distance sur 5 km (35 points) et date sur 5 ans (20 points). Il sert au classement et ne pondère pas le prix. Projection à votre surface : prix vendu × '+number.format(surface)+' m² ÷ surface vendue. Elle ne corrige pas le terrain, le nombre de pièces ni l’état du bien. Dernière vente retenue : '+new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium'}).format(new Date(latest))+'.</p><div class="sales">'+shown.map(s=>'<div class="sale"><div><strong>'+escape(s.street)+'</strong><small>'+new Intl.DateTimeFormat('fr-FR',{month:'short',year:'numeric'}).format(new Date(s.date))+' · '+number.format(s.area)+' m² · '+(s.rooms>0?number.format(s.rooms)+(s.rooms===1?' pièce · ':' pièces · '):'pièces n.d. · ')+(type==='Maison'?(s.land>0?'terrain '+number.format(s.land)+' m² · ':'terrain n.d. · '):'')+(s.km<1?number.format(s.km*1000)+' m':s.km.toFixed(1).replace('.',',')+' km')+'</small><span class="relevance '+(s.relevance>=75?'':s.relevance>=50?'mid':'low')+'">Pertinence '+s.relevance+'/100</span></div><div class="amount"><span class="amount-label">Prix vendu</span><strong class="actual-price">'+euro.format(s.price)+'</strong><small>'+number.format(s.sqm)+' €/m²</small><div class="projection"><span>Rapporté à votre surface</span><b>'+euro.format(s.sqm*surface)+'</b></div></div></div>').join('')+'</div><div class="notice">Ce repère repose sur les ventes enregistrées. Le terrain peut être absent ou partiel dans DVF ; l’état du bien, les travaux et les prestations ne sont pas pris en compte. Ce calcul ne constitue pas une expertise.</div><div class="sources">Données&nbsp;: <a href="https://www.data.gouv.fr/datasets/demandes-de-valeurs-foncieres" target="_blank" rel="noopener">DVF · DGFiP</a> · Localisation&nbsp;: <a href="https://adresse.data.gouv.fr/outils/api-doc/adresse" target="_blank" rel="noopener">BAN / IGN</a> et <a href="https://apicarto.ign.fr/api/doc/cadastre" target="_blank" rel="noopener">Cadastre / IGN</a>. '+number.format(sales.length)+' ventes valides repérées dans le secteur.</div></div>'}
    result.addEventListener('click',e=>{if(e.target.closest('.print-button'))window.print();if(e.target.closest('.new-estimate-button')){form.reset();syncPropertyType();setMode('address');result.dataset.state='idle';result.innerHTML=initialResultHtml;setSearchCollapsed(false);searchPanel.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}});
    form.addEventListener('submit',async e=>{e.preventDefault();const address=form.address.value.trim(),reference=form.elements.namedItem('parcel-ref').value.trim(),parcelCity=form.elements.namedItem('parcel-city').value.trim(),surface=Number(form.surface.value),type=propertyType.value,terrain=type==='Maison'?Number(form.terrain.value||0):0;if(mode==='address'&&!address||mode==='parcel'&&!reference||!Number.isFinite(surface)||surface<1||surface>1000)return;button.disabled=true;button.innerHTML='<span class="spinner" aria-hidden="true"></span>Recherche des ventes…';try{status(mode==='address'?'Localisation de l’adresse…':'Recherche de la parcelle…');const feature=mode==='address'?await geocode(address):await parcelLocation(reference,parcelCity),[lon,lat]=feature.geometry.coordinates,code=feature.properties.citycode;status('Recherche des secteurs cadastraux proches…');const cadas=await json('https://cadastre.data.gouv.fr/bundler/cadastre-etalab/communes/'+encodeURIComponent(code)+'/geojson/sections');let sections=(cadas.features||[]).map(f=>({code:dvfSectionCode(f.properties),km:boxDistance(lon,lat,bbox(f.geometry.coordinates))})).filter(s=>s.code!==null).sort((a,b)=>a.km-b.km).filter(s=>s.km<=10).slice(0,30);if(!sections.length)throw Error('Aucun secteur cadastral trouvé pour cette commune.');status('Lecture des ventes récentes autour de la maison…');let rows=await salesForSections(code,sections.slice(0,5)),sales=cleanSales(rows,lon,lat,surface,terrain,type),picked=choose(sales,surface,terrain);if((picked.tier.relaxed||picked.selected.length<6)&&sections.length>5){status('Recherche élargie aux rues voisines…');rows.push(...await salesForSections(code,sections.slice(5,14)));sales=cleanSales(rows,lon,lat,surface,terrain,type);picked=choose(sales,surface,terrain)}if((picked.tier.relaxed||picked.selected.length<4)&&sections.length>14){status('Recherche de repères dans les secteurs plus éloignés…');rows.push(...await salesForSections(code,sections.slice(14)));sales=cleanSales(rows,lon,lat,surface,terrain,type);picked=choose(sales,surface,terrain)}if(!picked.selected.length){message('Aucune vente du type choisi exploitable','Aucune vente exploitable trouvée dans les secteurs consultés de cette commune, jusqu’à 10 km sur les cinq dernières années, même sans filtre de surface.');return}render(feature,surface,terrain,sales,picked,type);if(window.matchMedia('(max-width: 800px)').matches){setSearchCollapsed(true);requestAnimationFrame(()=>result.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'}))}}catch(err){message('Estimation impossible',err.message||'Une erreur est survenue.',true)}finally{button.disabled=false;button.textContent='Estimer à partir des ventes'}});
    if(document.modelContext?.registerTool){
      const lifecycle=new AbortController();
      Promise.resolve(document.modelContext.registerTool({
        name:'estimate_house',title:'Estimer un bien',description:'Saisir une adresse française et une surface habitable pour afficher une estimation fondée sur les ventes DVF.',
        inputSchema:{type:'object',properties:{type:{type:'string',enum:['Maison','Appartement'],description:'Type de bien, Maison par défaut'},address:{type:'string',description:'Adresse avec code postal et commune'},surface:{type:'number',description:'Surface habitable en m²'},terrain:{type:'number',description:'Surface du terrain en m², facultatif'}},required:['address','surface'],additionalProperties:false},
        annotations:{readOnlyHint:false,untrustedContentHint:false},
        async execute(input){
          if(input.type!==undefined&&!['Maison','Appartement'].includes(input.type))throw Error('Type de bien invalide.');
          if(typeof input.address!=='string'||!/(^|\D)\d{5}(\D|$)/.test(input.address)||!Number.isFinite(input.surface)||input.surface<1||input.surface>1000||input.terrain!==undefined&&(!Number.isFinite(input.terrain)||input.terrain<0||input.terrain>100000))throw Error('Adresse avec code postal et surface de 1 à 1000 m² requises.');
          setMode('address');propertyType.value=input.type||'Maison';syncPropertyType();form.address.value=input.address;form.surface.value=String(input.surface);form.terrain.value=input.terrain===undefined?'':String(input.terrain);form.requestSubmit();
          return await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{observer.disconnect();reject(Error('La recherche a expiré.'))},60000);const observer=new MutationObserver(()=>{if(button.disabled)return;const title=result.querySelector('h2')?.textContent;if(title==='Recherche en cours')return;observer.disconnect();clearTimeout(timeout);if(title!=='Valeur indicative')reject(Error(result.innerText));else resolve({address:result.querySelector('.address')?.textContent,estimate:result.querySelector('.value')?.textContent,range:result.querySelector('.range')?.textContent,comparableSales:result.querySelector('.metric b')?.textContent})});observer.observe(result,{subtree:true,childList:true,characterData:true});});
        }
      },{signal:lifecycle.signal})).catch(()=>{});
    }
  })();
